    JOIN sort_it_out_sets st ON st.set_code = v.set_code
) AS s
ON t.question_code = s.question_code
WHEN MATCHED AND (t.set_id, t.prompt, t.correct_bucket, t.difficulty, t.points, t.explanation) IS DISTINCT FROM (s.set_id, s.prompt, s.correct_bucket, s.difficulty, s.points, s.explanation) THEN
    UPDATE SET set_id = s.set_id, prompt = s.prompt, correct_bucket = s.correct_bucket, difficulty = s.difficulty, points = s.points, explanation = s.explanation
WHEN NOT MATCHED THEN
    INSERT (question_code, set_id, prompt, correct_bucket, difficulty, points, explanation) VALUES (s.question_code, s.set_id, s.prompt, s.correct_bucket, s.difficulty, s.points, s.explanation)
WHEN NOT MATCHED BY SOURCE AND t.set_id IN (SELECT st.id FROM sort_it_out_sets st WHERE st.chapter_id IN (SELECT c.id FROM chapters c JOIN subjects sub ON sub.id = c.subject_id WHERE sub.code = 'economics')) THEN
    DELETE;
